mapper.select:
SELECT id
FROM public.finalization_operational_event
WHERE status IN ('PENDING', 'RETRY')
  AND next_attempt_at <= #{now}
ORDER BY next_attempt_at, id
LIMIT #{limit}

mapper.update:
UPDATE public.finalization_operational_event
SET status = 'SENT',
    telegram_message_id = #{telegramMessageId},
    sent_at = #{sentAt},
    lease_until = NULL,
    last_delivery_error_code = NULL,
    updated_at = #{sentAt}
WHERE id = #{id}
  AND status = 'PROCESSING'
  AND delivery_claim_version = #{deliveryClaimVersion}

UPDATE public.finalization_operational_event
SET status = 'RETRY',
    next_attempt_at = #{nextAttemptAt},
    lease_until = NULL,
    last_delivery_error_code = #{errorCode},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'PROCESSING'
  AND delivery_claim_version = #{deliveryClaimVersion}
